output_text:
[
  {
    "id": "take_cart_on_entry",
    "text": "A shopper is obliged to take the store cart before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_at_entrance": "cartAt(1,5)",
        "shopper_at_cart_rack": "at(1,5)",
        "holding_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "shopper_at_cart_rack",
              "cart_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Items should not be picked up unless the shopper is currently holding or pushing the cart, and items should not be carried by hand.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "holding_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "item_pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_taking",
    "text": "Once a shopper takes a cart, they are obliged to return it to the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "holding_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "holding_cart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_leave_cart_at_bay",
    "text": "A cart may not be put down anywhere except the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from leaving the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "holding_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "exit_requires_returned_cart",
    "text": "A shopper may exit only after the cart has been parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              {
                "not": "cart_parked_at_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "must_drop_cart_at_return_bay",
    "text": "When a shopper reaches the return bay while holding the cart, they must drop it there rather than move onward with it.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "arrived_at_return_bay_with_cart": {
          "pre": {
            "and": [
              "return_bay",
              "holding_cart"
            ]
          },
          "post": null
        },
        "drop_cart_at_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrived_at_return_bay_with_cart",
      "discharge": "drop_cart_at_return_bay"
    }
  },
  {
    "id": "no_cart_movement_from_return_bay",
    "text": "After reaching the return bay with a cart, the shopper is prohibited from making any movement action with the cart instead of leaving it there.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "return_bay": "at(0,1)"
      },
      "events": {
        "push_cart_out_of_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "holding_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_out_of_return_bay"
    }
  }
]
